CREATE TYPE user_role AS ENUM ('STUDENT', 'CLIENT', 'ADMIN');
CREATE TYPE gig_status AS ENUM ('OPEN', 'IN_PROGRESS', 'SUBMITTED', 'COMPLETED', 'CANCELLED');
CREATE TYPE application_status AS ENUM ('PENDING', 'ACCEPTED', 'REJECTED');

CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role user_role NOT NULL, avatar_url TEXT, suspended BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, college TEXT, course TEXT, year SMALLINT CHECK (year BETWEEN 1 AND 8), bio TEXT, availability TEXT, rating NUMERIC(2,1) NOT NULL DEFAULT 0, completed_gigs INT NOT NULL DEFAULT 0, earnings NUMERIC(12,2) NOT NULL DEFAULT 0);
CREATE TABLE skills (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE user_skills (user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, skill_id BIGINT REFERENCES skills(id) ON DELETE CASCADE, PRIMARY KEY (user_id, skill_id));
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE gigs (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, category_id BIGINT REFERENCES categories(id), budget NUMERIC(12,2) NOT NULL CHECK (budget > 0), deadline DATE NOT NULL, requirements TEXT, status gig_status NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE gig_skills (gig_id BIGINT REFERENCES gigs(id) ON DELETE CASCADE, skill_id BIGINT REFERENCES skills(id) ON DELETE CASCADE, PRIMARY KEY (gig_id, skill_id));
CREATE TABLE applications (id BIGSERIAL PRIMARY KEY, gig_id BIGINT NOT NULL REFERENCES gigs(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id), proposal TEXT NOT NULL, bid NUMERIC(12,2) NOT NULL CHECK (bid > 0), estimated_days INT NOT NULL CHECK (estimated_days > 0), status application_status NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (gig_id, student_id));
CREATE TABLE contracts (id BIGSERIAL PRIMARY KEY, gig_id BIGINT NOT NULL UNIQUE REFERENCES gigs(id), student_id BIGINT NOT NULL REFERENCES users(id), application_id BIGINT REFERENCES applications(id), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE submissions (id BIGSERIAL PRIMARY KEY, contract_id BIGINT NOT NULL REFERENCES contracts(id) ON DELETE CASCADE, notes TEXT, attachment_url TEXT, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id BIGSERIAL PRIMARY KEY, contract_id BIGINT NOT NULL REFERENCES contracts(id) ON DELETE CASCADE, author_id BIGINT NOT NULL REFERENCES users(id), recipient_id BIGINT NOT NULL REFERENCES users(id), rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), text TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (contract_id, author_id));
CREATE TABLE portfolio_projects (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, technologies TEXT[], github_url TEXT, live_url TEXT, image_url TEXT);
CREATE TABLE messages (id BIGSERIAL PRIMARY KEY, gig_id BIGINT NOT NULL REFERENCES gigs(id) ON DELETE CASCADE, sender_id BIGINT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, body TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reports (id BIGSERIAL PRIMARY KEY, reporter_id BIGINT REFERENCES users(id), gig_id BIGINT REFERENCES gigs(id) ON DELETE CASCADE, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX gigs_open_category_idx ON gigs(status, category_id, created_at DESC); CREATE INDEX applications_gig_idx ON applications(gig_id); CREATE INDEX messages_gig_created_idx ON messages(gig_id, created_at); CREATE INDEX notifications_user_idx ON notifications(user_id, created_at DESC);
